import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific Exploratory Landscape Analysis (ELA) features.

    The function combines a weighted sum of a sphere function, a Rosenbrock function, and a Rastrigin function,
    modulated by a Gaussian envelope. This creates a multimodal landscape with varying degrees of ruggedness and bias.

    Formula:
    f(x) = gaussian_envelope(x) * (0.2 * sphere(x) + 0.3 * rosenbrock(x) + 0.5 * rastrigin(x))

    where:
        x is a vector of decision variables.
        sphere(x) = sum(x_i^2)
        rosenbrock(x) = sum(100*(x_{i+1} - x_i^2)^2 + (1 - x_i)^2)
        rastrigin(x) = 10*n + sum(x_i^2 - 10*cos(2*pi*x_i))
        gaussian_envelope(x) = exp(-0.05 * sum(x_i^2))
    """
    n = len(x)

    def sphere(x):
        return np.sum(x**2)

    def rosenbrock(x):
        return np.sum(100.0 * (x[1:] - x[:-1]**2.0)**2.0 + (1 - x[:-1])**2.0)

    def rastrigin(x):
        return 10 * n + np.sum(x**2 - 10 * np.cos(2 * np.pi * x))

    def gaussian_envelope(x):
        return np.exp(-0.05 * np.sum(x**2))

    return gaussian_envelope(x) * (0.2 * sphere(x) + 0.3 * rosenbrock(x) + 0.5 * rastrigin(x))
